class TokenPair {
  const TokenPair({required this.accessToken, required this.accessTokenExpiresAt, required this.refreshToken, required this.sessionExpiresAt});

  factory TokenPair.fromJson(Map<String, dynamic> json) => TokenPair(accessToken: json['accessToken'] as String, accessTokenExpiresAt: json['accessTokenExpiresAt'] as String, refreshToken: json['refreshToken'] as String, sessionExpiresAt: json['sessionExpiresAt'] as String);

  final String accessToken;

  final String accessTokenExpiresAt;

  /// Single use. Store only in Keychain/Keystore. A reused refresh token revokes the session.
  final String refreshToken;

  final String sessionExpiresAt;

  Map<String, dynamic> toJson() => {'accessToken': accessToken, 'accessTokenExpiresAt': accessTokenExpiresAt, 'refreshToken': refreshToken, 'sessionExpiresAt': sessionExpiresAt};
